    faq_a_glib_friends: "Et tema for vennskap og varme med mennesker: få nye venner, lytte ordentlig, gjenoppta et gammelt vennskap, invitere venner hjem, et vennlig ord hver dag, og et smil og et hei. To små ideer i det kommer fra Dale Carnegies klassiker \"Hvordan vinne venner og få innflytelse på folk\" – å huske navn og å være oppriktig interessert i andre. Trykk på \"+ Lesekrok\" på bokkortet for å legge boka til i Lesekrok, under \"Skal lese\" – og så forsvinner kortet fra målene.",
