    faq_a_nm_me_card: "Ja. I \"Min figur\" (trykk på Sky i New Me) har hvert Sky-trinn du allerede har nådd, en liten delingsknapp i hjørnet. Den lager et glassaktig kort som et bilde – Sky som lyser mot en nattehimmel, trinnet, fornavnet ditt, dagen din på reisen og nøklene dine – og åpner delingsmenyen, så du kan sende det på WhatsApp eller lagre bildet. Det er bare et bilde, så venner kan se det, men ikke ta din Sky.",
