    bag_examples_v2_toast: "🎁 Nye eksempler i vesken din: gaveideer, en pakkeliste for hotellet og en for flyturen ✨",
    faq_a_bag_examples_list: "En ny veske kommer med eksempler som du kan endre eller slette som alt annet: Hjem (handleliste, oppskrifter, ukens måltider), Familie (små øyeblikk, en liste til bursdagsfesten, aktiviteter og kurs), Ideer (ideer til helgen, gaveideer etter hvor nær personen står deg, og hva du skal gjøre med sparepengene) og Turer (steder du vil dra, pakkeliste for turen, pakkeliste for hotellet og en liste for å fly til utlandet). En veske som fantes fra før, får de nyeste én gang, i sine egne lommer.",
    faq_q_bag_examples_list: "Hvilke eksempler finnes i Min veske?",
    faq_a_nm_me1_guide: "Sky – figuren din i New Me, i sin første form (Sky 1). Første gang, rett etter at du har blitt med, åpner en portal av lys seg med gnister rundt seg, og Sky flyr ut av den, forklarer med noen få trykk hva som venter, og blir så værende ved hvert spørsmål: mens måltidene velges, skriver han sammen med deg i boken sin, og et trykk på tipset viser et nytt. Til slutt feirer Sky med deg og tar deg med på en kort omvisning – og når omvisningen er over, har han ett lite øyeblikk til med deg. Hvis du går midt i – spørsmålene eller omvisningen – blir Sky glad for å se deg neste gang og spør om dere skal fortsette fra samme sted.",
    faq_q_nm_me1_guide: "Hvem viser vei inn i New Me?",
    nm_m1_day_text: "Hver dag – en ✓ på hvert måltid, og jeg teller alt for deg.",
