    nm_m1_hi_text: "Fra i dag er jeg her med deg – i hvert steg på veien.",
    nm_m1_hi_title: "Hei! Jeg er Sky",
    nm_m1_joy_btn: "En rask omvisning",
    nm_m1_joy_text: "Menyen din venter, og den magiske verdenen våkner allerede.",
    nm_m1_joy_title: "Hurra! Alt er klart",
    nm_m1_magic_text: "Og hvert ekte steg fremover du tar, åpner flere steder i den magiske verdenen",
    nm_m1_menu_text: "Sammen lager vi en meny helt etter deg: mat du elsker, til tider som passer deg.",
    nm_m1_portal: "En ny verden åpner seg",
    nm_m1_q_about: "Hyggelig å møte deg!",
    nm_m1_q_agree: "Før vi begynner – noen viktige ord",
    nm_m1_q_letter: "Noen ord til ditt fremtidige jeg? Jeg tar godt vare på dem for deg",
    nm_m1_q_menu: "La oss skrive drømmene sammen – og gjøre dem til virkelighet sammen",
    nm_m1_q_plan: "Du kan bytte når som helst – her finnes ingen feil valg.",
    nm_m1_q_times: "Dine tider er mine tider også",
    nm_m1_ready_text: "Først noen små spørsmål – så velger vi måltidene sammen.",
    nm_m1_skip: "Hopp over",
    nm_m1_tip_ai: "En matrett som ikke står på listen? Senere kan du skrive den med egne ord under «Bytt» – og AI regner den ut. Og nå velger vi sammen hva du skal spise hver dag.",
    nm_m1_tip_love: "Og hvis du ikke elsker noe – du kan alltid bytte det ut med AI. Det spiller ingen rolle hvilken mat – elsker du den, blir den på menyen.",
    nm_m1_tip_rice: "Ris elsker jeg mest – det blir basen min, så jeg velger det. Jeg anbefaler å gå for det som er kjent og godt.",
    faq_a_shop_basics: "Når Handlelisten er helt tom – for eksempel helt i starten – vises en grunnliste å starte med: melk, brød, egg og mer. Et trykk på en vare legger den til på listen, og «Legg til alle» legger til alt på én gang. Så snart noe står på listen, forsvinner grunnlisten.",
    faq_q_shop_basics: "Hva er grunnlisten i en tom Handleliste?",
    shop_basics_all: "Legg til alle",
    shop_basics_items: "melk|brød|egg|tomater|agurk|ost|ris|pasta|olivenolje|epler|bananer|toalettpapir",
    shop_basics_title: "En grunnliste å starte med",
    shop_order_empty: "Listen er tom akkurat nå",
    shop_order_hours: "Når på dagen?",
    shop_win_evening: "Kveld",
    shop_win_from: "Fra",
    shop_win_morning: "Formiddag",
    shop_win_noon: "Ettermiddag",
    shop_win_other: "Annet…",
    shop_win_to: "Til",
    room_genie_again_no: "Ikke akkurat nå",
    room_genie_again_no_msg: "Da er det på tide å nå målene du allerede har satt deg. Når du kommer til det neste – venter noe på deg der ✨",
    room_genie_again_q: "Tilbake igjen? ✨ Vil du gjerne forandre noe mer i livet ditt?",
    room_genie_again_yes: "Ja",
    room_genie_bye: "Vi ses",
    room_genie_rest: "Skogsånden hviler nå – kom tilbake i morgen ✨",
    faq_a_shop_holidays: "Trykk på gaven i Handlelisten: høytidene i landet ditt (det som er valgt i Innstillinger) vises i rekkefølge, med datoer – som regnes ut av seg selv hvert år. Trykk på en høytid for en ferdig liste over det folk pleier å kjøpe til den; alt er valgt (unntatt det som allerede står på listen din), fjern haken for det du ikke trenger, og trykk på «Legg til i listen». To uker før en høytid dukker et lite kort opp øverst i listen; ✕ skjuler det til neste høytid.",
    faq_q_shop_holidays: "Hvordan fungerer «Hva skal kjøpes til høytiden»?",
    shop_hol_add: "Legg til i listen ({n})",
    shop_hol_added: "Lagt til i listen: {n}",
    shop_hol_btn: "Hva skal kjøpes til høytiden",
    shop_hol_items_title: "{holiday} – hva skal kjøpes?",
    shop_hol_not_now: "Ikke nå",
    faq_a_shop_delivery: "Trykk på lastebilen i Handlelisten: velg hva som er med i leveringen (alt er valgt), når den kommer – i dag, i morgen eller en annen dag – og når på dagen (formiddag, ettermiddag, kveld eller «Annet…» for egne tider). Disse varene flyttes til kortet «På vei» øverst i listen, med dagen og tidene. Når dagen kommer, dukker «Har leveringen kommet?» opp i Min Dag (og kortet har «Har den kommet?»). Har alt kommet, flyttes de til «Kjøp igjen». Mangler noe, trykker du på det som ikke kom, så går det rett tilbake til listen.",
    faq_a_shop_departments: "Listen sorterer seg selv etter avdelingene i butikken – frukt og grønt, brød, meieri og egg, kjøtt og fisk, tørrvarer, frysevarer, drikke, snacks, rengjøring, hygiene, baby og dyr – så du går gjennom hyllene i rekkefølge. Avdelingen kjennes igjen på navnet til varen. Havnet en vare på feil sted, trykk på den og velg avdeling, eller «Annet…» for å skrive din egen.",
    faq_a_shop_share_qty: "Ja. Ved siden av hver vare legger + til én (×2, ×3…) og − tar bort én. Del-knappen øverst i Handlelisten sender hele listen, pent sortert etter avdeling, på WhatsApp, e-post eller som en kopi.",
    faq_a_shop_two_buttons: "Begge betyr «kjøpt». ✕ er for noe du kjøper én gang – det forsvinner fra listen (og venter i arkivet 🗑️ i tilfelle det var en feil). ↺ er for ting du kjøper igjen og igjen – de forsvinner fra listen og venter i «Kjøp igjen»: den lille ↺-knappen ved siden av søppelbøtta nederst i listen åpner det, og ett trykk der setter en vare tilbake på listen. Under «Rediger» der inne kan du ta en vare ut. Når du legger til en vare, dukker ting du har kjøpt før opp som forslag, og står den allerede på listen, blir den bare ×2 i stedet for en ny linje.",
    faq_q_shop_delivery: "Hvordan fungerer «Jeg har bestilt levering»?",
    faq_q_shop_departments: "Hvorfor er handlelisten min delt inn i avdelinger?",
    faq_q_shop_share_qty: "Kan jeg angi en mengde eller sende listen til noen?",
