    nm_demo_title: "Slik fungerer et bytte",
    faq_a_new_me_challenge_journal: "Når en utfordring er over – stor, mini eller ukens utfordring – har feiringen en knapp 📝 Hvordan gikk det?, som åpner en side i utfordringsdagboken: hvordan det føltes (fem ansikter), hva som hjalp, hva som var vanskelig og hva jeg tar med meg videre – ingenting er obligatorisk, og det kan også vente til senere. Dagboken er en diamant i den magiske ryggsekken: hver fullførte utfordring med dato og det som ble skrevet, den nyeste først – trykk på en for å lese, redigere eller dele den (bare det som står på siden, deles). En fullført utfordring får også en medalje under prestasjonene, i «Utfordringer jeg har fullført». Utfordringsdagboken er atskilt fra den vanlige dagboken.",
    faq_q_new_me_challenge_journal: "Hva er utfordringsdagboken?",
    nm_badges_challenges: "Utfordringer jeg har fullført",
