    nm_chj_share_text: "Jeg fullførte en utfordring i New Me ✨",
    nm_chj_take: "Hva tar jeg med meg videre?",
    nm_chj_title: "Utfordringsdagbok",
    nm_chj_write: "Skriv hvordan det gikk",
    nm_swap_time: "Tid",
    faq_a_ai_reminder_in_text: "Ja – skriv den sammen med oppgaven, for eksempel «i morgen kl. 17:00 hente pakken, med en påminnelse en time før». Påminnelsen lagres på selve oppgaven: en time før, en halvtime, dagen før og så videre, og «påminn meg» uten tid betyr 10 minutter før. En påminnelse skrevet i teksten går foran påminnelsesfeltet i samme vindu.",
    faq_q_ai_reminder_in_text: "Kan jeg be AI-assistenten om en påminnelse i samme forespørsel?",
    myday_meals_all_done: "Alle dagens måltider er krysset av 🍽️",
    nm_tour_week_text: "En liten utfordring for uken. ✓ hver dag – en nøkkel til slutt.",
    books_home_chip: "{title} · s. {page}",
    books_home_of: "av {total}",
    books_home_off_toast: "Boken er fjernet fra startskjermen",
    books_home_on_toast: "Boken er på startskjermen 📖",
    books_home_pin: "På startskjermen",
    books_home_q: "Hvilken side er jeg på?",
    books_home_save: "Lagre",
    faq_a_books_home_chip: "Ja. I Lesekrok, på kortet til en bok du leser nå, trykker du på 📌 På startskjermen. En liten knapp med boken og siden vises under hilsenen på startskjermen – trykk på den, skriv inn det nye sidetallet og lagre, så følges fremgangen (også i Lesekrok). Trykk på 📌 igjen, så tas den bort. Flere bøker kan ligge der samtidig – en knapp for hver – og likt på alle enheter.",
    faq_a_new_me_week_challenge: "En liten utfordring for én uke, som du velger selv. I gangen er det et stort kort: «Hva vil du jobbe med denne uken?» – trykk på det, velg et område (med meg selv, med andre, lære og vokse, ro, små modige steg, hjem og rutiner) og en utfordring, og velg når den starter. De samme utfordringene finnes også på utfordringsskjermen, under 🌱 Personlig utvikling. Hver dag krysser du av ✓ på kortet (én fridag i uken), og hver uke som er over, gir en ny nøkkel til den hemmelige verdenen. «Lese 2 sider om dagen» krysses av automatisk ut fra sidene som logges i Lesekrok. Når uken er over, legger 📌 Behold som daglig oppgave den til i Min Rutine på klokkeslettet du velger, med en ✓ hver dag. Én ukeutfordring pågår om gangen; de store utfordringene og miniutfordringene fortsetter ved siden av.",
    faq_a_room_genie: "På verandaen ved havet får et trykk på Aladdins lampe skogsånden til å stige frem – og en samtale begynner: hva er ønsket ditt (hva vil du gjerne forandre i livet ditt), hvordan det kjennes når det går i oppfyllelse, hva som er vanskelig på veien, og hvordan situasjonen akkurat nå kan gjøres om til noe godt. Så omtrent hvor lang tid det tar, et første lite steg og to til, og et «hvis… så…» for når det blir vanskelig. Til slutt vises hele ønsket steg for steg, og det kan bli et mål i Mine Mål (stegene blir milepæler på stien, med dato etter tiden som er valgt; der kan alt endres) eller lagres i dagboken – og så sier skogsånden farvel. Ingenting lagres med mindre man velger en av dem. Fra andre besøk spør skogsånden først om du gjerne vil forandre noe mer i livet ditt: ja – den samme samtalen; ikke akkurat nå – en påminnelse om å nå målene som allerede er satt. Skogsånden kommer frem én gang om dagen: når et ønske er lagret (eller etter «Ikke akkurat nå»), hviler den til i morgen. Spørsmålene følger en kjent måte å gjøre et ønske om til en plan: ønske, utfall, hindring og plan.",
    faq_q_books_home_chip: "Kan jeg se boken og siden min på startskjermen?",
    faq_q_new_me_week_challenge: "Hva er ukens utfordring?",
    faq_q_room_genie: "Hva gjør ånden i lampen?",
