    faq_a_new_me_game: "I New Me blir spillknappene alltid på samme sted – i gangen, i det hemmelige rommet og overalt i skogen; bare maleriet i midten skifter. Øverst: dagen på reisen, nøkler, dager på rad og dagens energi (hvor mye som er spist av planen), og under det neste oppdrag – neste måltid med klokkeslett (et trykk åpner det, med ✓ Jeg har spist). På siden: hele dagen, utfordringer og min reise, og ved siden av dem ukens utfordring – de 7 dagene og en ✓ for i dag. Nederst: den magiske ryggsekken (hele New Me – verdenskartet, min reise, handleliste, prestasjoner, utfordringsdagbok, kroppsmål, bilder, månedskalender, dagstabell, påminnelser, meny-PDF og innstillinger; den åpnes som en egen skjerm). Verdenskartet, det første i ryggsekken, viser alle stedene i skogen – trykk på et sted for å gå dit; på et låst sted ser du hvor mange nøkler det trenger. Sky er figuren din på skogsstien: han begynner som Sky 1, etter noen utfordringer (4 nøkler) vokser han til Sky 2 og mot slutten (9 nøkler) til Sky 3 – med en forvandling du kan se på. Trykk på Sky for å se alle trinnene – hvert trinn du allerede har nådd, kan velges igjen, så et tidligere kan komme tilbake. Sky svever – dra ham med fingeren eller musen, og inngangen han berører, åpnes (en låst viser hvor mange nøkler som mangler). Sky blir også med inn i hvert rom og på hvert sted og svever der du lar ham være: dra ham hvor du vil, og dra den lysende ringen under ham for å snu ham helt rundt; han ser i den retningen han beveger seg (på en datamaskin: pilene flytter ham, Q og E snur ham). I gangen går den lille 🏠 under topplinjen tilbake til startskjermen; i hvert rom og på hvert sted går knappen i samme hjørne tilbake til gangen.",
    faq_q_new_me_game: "Hvordan fungerer spillknappene, verdenskartet og Sky?",
