    faq_a_new_me_menu_build: "Først spør spørreskjemaet hvilke måltider du spiser og når (2 måltider + et mellommåltid, 2 måltider + en lett middag, eller begge), og om det er noe om kvelden – å spise eller drikke, hva og når. Med «2 måltider + et mellommåltid» er måltidene lunsj (11:30) og middag (19:00), med mellommåltidet kl. 16:00. Så vises alle alternativene for de måltidene. Velg opptil 2 favoritter til hvert måltid – i menyen står det «det ene eller det andre». I noen alternativer (pita og pålegg, cornflakes og melk, noe lett) velger du opptil 3 ting du liker, hver i sin egen porsjon, og i menyen står det «det ene eller det andre eller det tredje»; kaloriene følger det du har valgt. Kaffe og drikke fungerer på samme måte. Hvert valg balanseres, så dagen blir nøyaktig 1 300 eller 1 500. For å endre når som helst: ⚙️ Innstillinger → 🍽️ Lag menyen din, eller «Velg opptil 3 du liker» på måltidets kort.",
    faq_q_new_me_menu_build: "Hvordan bygges New Me-menyen opp?",
