    faq_a_myday_water_toggle: "Ja. Vannglasset i 'Min Dag' (med + for ett glass til) vises som standard. For å skjule det, slå av «Vis vann i 'Min Dag'» i Innstillinger > Personalisering og kalender. Ingenting slettes – vannsporingen fortsetter å virke, og når bryteren slås på igjen, kommer glasset tilbake.",
    faq_q_myday_water_toggle: "Kan jeg skjule vannet i 'Min Dag'?",
    myday_water_toggle_label: "Vis vann i 'Min Dag'",
    faq_a_routine_newme_sync: "Med New Me har ⚙️ i Min Rutine en bryter 'Synkroniser med New Me'. Når den er på (standard), vises dagens New Me-måltider i Min Dag og i Min Rutine – i stedet for rutinemåltidene som ble skjult. Når den er av, forsvinner New Me-måltidene fra begge, og rutinen blir akkurat som før. Ingenting slettes – slår du den på igjen, kommer alt tilbake, og du blir spurt hvilke rutinemåltider som skal skjules.",
    faq_q_routine_newme_sync: "Hvordan slår jeg synkroniseringen av New Me med Min Rutine og Min Dag på eller av?",
