    faq_a_food_list_languages: "Den innebygde matlisten startet med israelske retter og deres hebraiske navn. På alle andre språk vises hver matvare med det engelske navnet, og søket finner alle engelske navn det kjenner (for eksempel finner 'broth' Clear soup); matvarer som bare har et hebraisk navn, vises ikke der. Det som ikke står i listen, kan du ganske enkelt skrive med egne ord – AI-anslaget fungerer på alle språk.",
    faq_q_food_list_languages: "Hvorfor viser matlisten engelske navn, og færre matvarer, på mitt språk?",
    settings_copyright_line: "© 2026 alle rettigheter forbeholdt. appen er utviklet av eden zabari.",
    workout_ready_replace_btn: "Erstatt",
    faq_a_sport_workout_ai: "I Mine treningsøkter → ⋯ → Plan med AI (og når tabellen er tom, også på flisen ved siden av de ferdige planene). Svar med noen trykk – hvor mange ganger i uken, når, sted, nivå og mål, nesten alle med \"Annet\" også – og legg gjerne til en fri linje, som et ømt kne eller å løpe 5 km innen sommeren. AI-en lager en hel uke: typer økter, dager, tider, varighet, intensitet, øvelser og hviledager. Før noe lagres, vises en forhåndsvisning: \"Legg inn i tabellen min\" (i stedet for tabellen eller i tillegg), \"Et annet forslag\" (opptil 3 ganger) eller \"Endre svar\". Planen er moderat med vilje, og nevner du smerte eller en skade, får du skånsomme valg og rådet om å snakke med en fagperson. Den bruker samme AI-kvote som timeplanen og rutinen: 5 ganger gratis og 60 ganger i måneden med Premium.",
    faq_q_sport_workout_ai: "Hvordan lager jeg en treningsplan med AI?",
