    workout_ai_when_morning: "Morgen",
    workout_ai_when_noon: "Midt på dagen",
    workout_ai_when_ph: "f.eks. etter jobb, eller 17:30",
    workout_ai_working: "Planen lages…",
    faq_a_sport_workout_jar: "Hver type økt har sin egen fargede stjerne – løping rosa, gåtur grønn, svømming blå og så videre. Hver økt du logger denne uken, fra planen eller for seg, slipper stjernen sin ned i glasset øverst i Mine treningsøkter, og glasset fylles opp mot ukemålet ditt (trykk på det for å endre målet). Når du når målet, gløder glasset. Det lille glasset ved siden av teller hvor mange uker på rad du fylte det.",
    faq_q_sport_workout_jar: "Hva er de fargede stjernene og glasset i Mine treningsøkter?",
    faq_a_sport_workout_gcal: "Ja – under ⋯ → Google Kalender (når Google Kalender er koblet til i Innstillinger). Hver økt med et tidspunkt blir en hendelse som gjentas hver uke på sine dager, og endringer i appen oppdaterer den. Påminnelser kommer bare fra appen, så Google legger ikke til egne, og øktene vises aldri dobbelt i appen. Et nytt trykk fjerner bare treningsøktene fra Google Kalender.",
    faq_q_sport_workout_gcal: "Kan treningsøktene mine vises i Google Kalender?",
    workout_gcal_btn: "Google Kalender",
    workout_gcal_error: "Google Kalender kunne ikke oppdateres – det prøves igjen ved neste endring",
    workout_gcal_not_connected: "Koble til Google Kalender i Innstillinger først",
    workout_gcal_off_toast: "Treningsøktene ble fjernet fra Google Kalender",
    workout_gcal_on_toast: "Treningsøktene dine er i Google Kalender",
    faq_a_sport_workout_reminder: "Ja – i en økt, Påminnelse: 10 minutter, 30 minutter eller en time før, eller en egen tid (økten trenger et tidspunkt). Den ringer som de andre påminnelsene dine, én gang og ett sted: i appen hvis den er åpen, ellers på telefonen. \"Ferdig\" logger økten i historikken, og \"Ikke ennå\" minner deg på igjen om 5 minutter.",
    faq_q_sport_workout_reminder: "Kan jeg få en påminnelse før en økt?",
    workout_reminder_30min: "30 minutter før",
    workout_reminder_label: "Påminnelse",
    workout_reminder_need_time: "Legg til et tidspunkt for å få en påminnelse",
    faq_a_sport_workout_share: "Under ⋯ → Del blir uken et glassaktig bilde i fargene til temaet ditt, med en diskret lenke til appen (på telefonen går den rett til delingsmenyen, på datamaskinen lagres bildet). ⋯ → PDF for utskrift åpner en ryddig side med hele uken og en rute å krysse av ved hver økt og øvelse – velg \"Lagre som PDF\" eller skriv ut. Planen finnes også i datarapporten i Innstillinger, under Sport.",
    faq_q_sport_workout_share: "Hvordan deler eller skriver jeg ut treningsuken min?",
    share_image_saved: "Bildet er lagret – du kan legge det ved",
    share_save_image: "Lagre bildet",
    workout_pdf_btn: "PDF for utskrift",
    workout_share_btn: "Del",
    faq_a_sport_workout_board: "Under ⋯ → Ukestavle er hver dag en kolonne: dra en økt til en annen dag (på telefonen, hold inne først). I en økt legger \"Også i Min Rutine\" den inn i rutinen din på dens tid og dager, og endringer holdes i synk begge veier; fra et punkt i Min Rutine gjør \"Legg til i mine treningsøkter\" det motsatte. En ✓ ett sted teller begge steder, og i Min Dag vises den bare én gang – i brikken ved siden av vannet.",
    faq_q_sport_workout_board: "Hvordan flytter jeg en økt til en annen dag og kobler den til Min Rutine?",
    routine_in_workouts_btn: "Åpne i mine treningsøkter",
    routine_to_workout_btn: "Legg til i mine treningsøkter",
    routine_to_workout_done: "Lagt til i mine treningsøkter 💪",
    workout_delete_confirm_routine: "Den fjernes fra planen og fra Min Rutine. Økter som allerede er logget i historikken, blir værende.",
    workout_moved: "Flyttet til {day}",
    workout_routine_need_time: "Legg til et tidspunkt for å legge den i Min Rutine",
    workout_routine_toggle: "Også i Min Rutine",
    workout_view_board: "Ukestavle",
    workout_view_timeline: "Tidslinje",
    faq_a_sport_workout_plan: "I Treningssporing, under \"Mine treningsøkter\": + Økt – type, dager, tid, varighet, intensitet og sted (også \"Annet\"). Styrke-, funksjonelle og svømmeøkter kan ha en liste med øvelser, og Hvile markerer en hviledag. Du kan også starte fra en ferdig plan. Dagens økt vises stort, med hele uken under; ✓ logger den i treningshistorikken sammen med intensiteten. Under ⋯ setter du et ukemål (økter eller minutter) – hver økt du gjør slipper stjernen sin ned i glasset.",
    faq_a_sport_workout_today: "I Min Dag, ved siden av vannet, viser en liten brikke dagens økt – et trykk åpner detaljer, ✓ og ▶. ▶ starter en tidtaker som fortsetter i brikken på startskjermen, og \"Avslutt\" logger økten med den virkelige tiden. Hvis utfordringen \"To uker i bevegelse\" i New Me pågår, teller en logget økt der av seg selv.",
    faq_q_sport_workout_plan: "Hvordan planlegger jeg treningsuken min?",
