    faq_a_new_me_magic_themes: "Fem glitrende temaer som følger med New Me: Fortryllet skog, Stjernestøv, Rosefe, Magisk nordlys og Gyllen skumring. Velg ett i New Me (⚙️ Innstillinger > Farger) eller under Innstillinger > Utseende og skjerm, så maler en glitterpensel skjermen i det temaet. Et magisk tema gir glitter i hele appen og ved hvert trykk. Du kan gå tilbake til et hvilket som helst annet tema når som helst.",
