    apptour_focus_text: "Alt trer til side unntatt den ene tingen akkurat nå – med en stor ✓. Så dukker den neste opp.",
    apptour_m_presets_text: "De lagrede måltidene dine på ett sted: søk, nylig brukt, etter tid på dagen – og ＋ legger til ett for i dag.",
    apptour_night_text: "🌙 gjør hele appen mørk, ☀️ henter dagen tilbake.",
    apptour_noteline_text: "Skriv og trykk på ➤ – det lagres i notatene dine. 📝 i starten bytter til 🛒 handleliste eller 🍎 et lagret måltid.",
    apptour_search_text: "Notater, handling, kalender, oppskrifter, notatbøker, mål, tabeller og bøker – ett søk finner alt.",
    faq_a_new_me_ai_menu: "Før menyen spør spørreskjemaet hvilke måltider du spiser og når (2 måltider + et mellommåltid, 2 måltider + en lett middag, eller begge), om du spiser noe lite om kvelden og når, hva du ikke spiser og hvordan du drikker kaffe eller te. Så lager AI 3 forslag til hvert måltid – hvert like stort som måltidets andel av dagen, så dagen fortsatt blir nøyaktig 1 300 eller 1 500 – pluss drikkeideer som lagres som dine faste drikker. Velg opptil 2 favoritter per måltid; forslagene fra den opprinnelige menyen ligger rett under, og under 🔄 Bytt kommer de etter den personlige menyen. 🔄 Andre forslag lager et nytt sett (3 ganger per spørreskjema). For å endre svarene eller lage en ny meny når som helst: ⚙️ Innstillinger → ✨ Personlig meny (AI).",
