    nm_sales_premium: "Hele Premium er inkludert",
    nm_unlock_premium: "Og hele Premium er låst opp også.",
    settings_sub_status_newme: "Premium er inkludert i din New Me.",
    room_back_to_shelf: "Til hylla",
    faq_a_new_me_day_total: "Hver dag ender nøyaktig på planen: måltidene, rundt 150 kalorier til kaffe og drikke i løpet av dagen, og det som er valgt til kvelden – noe lite å spise eller noe å drikke. Til kvelden velger du opptil 3 du liker (for eksempel en banan, en yoghurt eller 2 ruter mørk sjokolade; eller urtete, te med litt melk eller varm melk), og kaloriene deres trekkes fra måltidene. Hvert valg balanserer seg selv: et mindre eller større alternativ, et måltid som er tatt bort, den lille frokosten og det lille måltidet som følger med den, eller kvelden – forskjellen legges til måltidene eller trekkes fra dem, hvert etter sin størrelse, og under hvert måltid står det hvor mye (+ eller −) og hva som kan legges til eller tas bort. Et måltid som allerede er krysset av, blir stående slik det ble registrert. I spørreskjemaet viser hvert måltid sin justering, og en liten boks viser måltider, drikke, kvelden og totalen. Lyst på noe annet den dagen? Hold totalen på like mange kalorier eller færre.",
    faq_q_new_me_day_total: "Hvordan ender en New Me-dag på nøyaktig 1 300 / 1 500, og hvor teller drikke?",
