    nm_swap_balanced: "{n} kalorier fordelt på måltidene, så dagen ender på {plan}",
    books_quotes_chip: "Sitater",
    faq_a_book_quotes: "På hyllen i det hemmelige rommet (Sitater), eller med den lille etiketten 💬 Sitater i Lesekroken – det er den samme listen. Trykk på «+ Sitat», skriv setningen og velg boken fra Lesekroken, eller skriv en annen tittel med «✏️ Annet»; forfatteren er valgfri. ✏️ endrer et sitat og 🗑️ sletter det. Sitatene er bokmerker du sveiper mellom – 🎨 øverst bytter til bilder eller en vegg av kort.",
    faq_a_room_wish_jar: "På hyllen i det hemmelige rommet står et glass for drømmer. Trykk på det lille glasset på øverste hylle (eller Hylla > Ønskeglasset) og skriv hvordan du vil at livet ditt skal se ut – så vilt du vil, uten rett eller galt. Hvert ønske brettes til en lapp som faller ned i glasset. «Trekk en lapp» åpner en tilfeldig, og hver lapp kan også åpnes for seg. Fra andre gang du åpner det samme ønsket, kan du gjøre det til et mål og dele det opp i små steg. Én gang i uken dukker en lapp med et av ønskene dine stille opp – uten press, bare en påminnelse om hvor du er på vei.",
    faq_q_book_quotes: "Hvor lagrer jeg sitater fra bøker jeg har elsket?",
