    room_wish_written: "Skrevet {date}",
    faq_a_saved_meals_page: "Lagrede måltider har en egen side: Ernæring og Målinger > ⭐ Lagrede måltider (eller ⭐ i menyen). Søket øverst finner et måltid på navn eller ingrediens, «Nylig brukt» viser det du har lagt til i det siste, og fanene (Frokost, Lunsj, Middag, Supper…) viser hver tid på dagen. «+ I dag» legger et måltid inn i dagens Daglige Måltidssporer, på neste ledige plass. Trykk på et måltid for å endre eller slette det, og ＋ øverst legger til et nytt.",
