    presets_tab_soup: "Supper",
    presets_tab_sweet: "Godteri",
    faq_a_notes_sticky_look: "Notater er en kort liste med glasskort – 🎨 øverst i Notater bytter utseende på hele Notater: listen, dagknappene øverst og vinduet der et notat skrives – glass, ren liste, kartotekkort eller washitape. Et notat som dras, beholder nøyaktig sitt eget utseende og sin egen farge. Trykk på teksten i et notat for å åpne det – der kan du endre det, bytte farger og se når det sist ble skrevet. Trykk på ○ når det er gjort, og × flytter det til arkivet (🗑️ nederst i listen henter det tilbake). Dra det i ⠿ for å endre rekkefølgen, til under «Senere» eller til en dag øverst. ! markerer et notat som haster – det glir forsiktig opp til de første radene med en liten «Haster»-merkelapp; et nytt trykk fjerner markeringen.",
    faq_q_notes_sticky_look: "Hvordan åpner, endrer eller fjerner jeg et notat?",
    note_to_archive_btn: "Flytt til arkivet",
    faq_a_routine_clash: "Står det allerede noe på det tidspunktet de samme dagene, får du to valg: «Erstatt» – det nye får det tidspunktet, og du velger et annet tidspunkt for det som sto der (når du redigerer noe som finnes fra før, foreslås det forrige tidspunktet, så de to bare bytter plass), eller «Begge» – begge blir stående på samme tidspunkt, den ene under den andre. Er dagene forskjellige (for eksempel den ene søn–tor og den andre fredag), spørres det ikke om noe.",
    faq_q_routine_clash: "Hva skjer hvis jeg legger noe i rutinen på et tidspunkt som allerede er tatt?",
    routine_clash_both: "✌️ Begge – begge klokken {time}",
    routine_clash_move_btn: "Flytt og lagre",
    routine_clash_move_to: "Hvilket tidspunkt skal «{title}» flyttes til?",
