    routine_clash_title: "Klokken {time} står det allerede: {title}",
    faq_a_new_me_coffee: "Under dagens meny står en kort oppsummering: hvor mange kalorier alle dagens måltider blir til sammen, hvor mye som er igjen til kaffe og drikke, og knapper for kaffen og drikkene som er valgt – ett trykk legger det til under Drikke. I «Velg opptil 3 du liker» under knappene (og i spørreskjemaet) velger du hva som vises: vann / kullsyret vann, urtete, en light-brus, svart / americano (~5), te med litt melk (~25), vannbasert kaffe med opptil 100 ml melk eller plantedrikk (~50), lett kakao, varm melk eller vanlig kaffe / latte (~120).",
