    nm_late_room_line: "Noe lite før leggetid · ~{n} kcal igjen i dag",
    faq_a_recipe_examples: "Under dine egne oppskrifter finnes eksempeloppskrifter: frokost, salater, supper, hovedretter, tilbehør, mellommåltider, desserter og veganske retter, hver med tilberedningstid, kalorier per porsjon og hvor mange gram én porsjon veier. Trykk på en oppskrift for å åpne den, og «Lagre i Mine Oppskrifter» lager din egen kopi som du kan redigere. Kategorietikettene filtrerer, og et nytt trykk på samme etikett viser alt igjen.",
    faq_a_recipe_grams: "I en oppskrift står det ved siden av kaloriene «1 porsjon ≈ X g». For dine egne oppskrifter fyller du inn «Gram per porsjon» (og tilberedningstiden om du vil) i oppskriftsskjemaet: begge er valgfrie, og tiden vises på oppskriftens fargebånd.",
