    recipes_examples_title: "Eksempeloppskrifter",
    faq_a_recipe_scan_multi: "Ja. I «Legg til Oppskrift» trykker du på 📷 og velger ett bilde eller flere (opptil 6; en PDF fungerer også). Hvert bilde vises i en kort liste der du velger hva det viser: Alt, Ingredienser eller Fremgangsmåte, og «➕ Ett bilde til» legger til flere. Trykk så på «✨ Skann oppskriften»: AI-en setter alt sammen til én oppskrift, i riktig rekkefølge og uten doble linjer, og det teller som én skanning. Flere bilder du velger under 📷 Bilde i AI-assistenten åpnes også her.",
    faq_q_recipe_scan_multi: "Kan jeg skanne én oppskrift fra flere bilder, for eksempel ingrediensene og fremgangsmåten hver for seg, eller to sider?",
