    faq_a_note_written_at: "Trykk på teksten i notatet for å åpne det. Inni, under teksten, står det når det sist ble skrevet, med nøyaktig dato og klokkeslett. Bare en endring i selve teksten oppdaterer det: arkivering og gjenoppretting, avkrysning ✓, farger eller flytting av notatet endrer det ikke.",
