    note_written_at: "Sist skrevet: {date}",
    faq_a_new_me_month: "I den magiske ryggsekken → Månedskalender: hver dag er farget etter hvor mange måltider som ble krysset av, pilene ‹ › bytter måned, og under kalenderen står månedens snitt av kalorier per dag. Et trykk på en dag viser hvor mange måltider som ble krysset av og hvor mange kalorier som ble spist den dagen.",
