    nm_month_day_line: "Avkryssede måltider: {checks} · kalorier: {kcal}",
    nm_extra_line_small: "{n} kalorier til dette måltidet, fra den lille frokosten – f.eks. {ideas}",
    faq_a_new_me_small_breakfast: "En lett frokost (ca. 170 kcal): en speltpita (opptil 100 kcal) med pålegg eller ost samt en grønnsak – velg opptil 3 du liker, for eksempel 1 ts sjokoladepålegg, 1 ts peanøttsmør eller en skive gulost (opptil 22 %). Fordi den er liten, følger «Pluss et lite måltid» med på et annet tidspunkt (halvannen time senere, for eksempel 11:30 → 13:00 – et hvilket som helst annet tidspunkt kan velges): en pita til med pålegg, proteinyoghurt og frukt, riskaker og cottage cheese, frokostblanding og melk eller halv pita og egg – opptil ca. 200 kcal, med sin egen ✓. Det som fortsatt er igjen, fordeles på de andre måltidene, og hvert måltid viser hvor mye det fikk, så dagens sum blir som i planen. Velg den i spørreskjemaet, eller bytt til den bare for i dag med 🔄 – for eksempel når frokosten blir sen.",
    faq_q_new_me_small_breakfast: "Hva er den «lille frokosten» i New Me-menyen?",
