    faq_a_ai_icon: "Ja – under Innstillinger > Utseende og skjerm. Den myke boblen er standard, og med Premium kan du også velge en svevende hjerne eller en robot.",
    faq_a_new_me_favorites: "Ja. I spørreskjemaet (og når du tar det på nytt fra innstillingene) kan du velge opptil 2 alternativer for hvert måltid. Det første står i menyen, med en «eller»-linje under for det andre – et trykk på den bytter til det bare for i dag. Og hvis frokosten ikke ble spist i tide, flytter «⏰ Senere» den til senere på dagen, uten at kaloriene endres.",
    faq_a_theme_mode: "Noen spesialtemaer er finest i mørkt – Akvarell, Nordlys, Barbie og de to glittertemaene –, så velger du ett av dem, bytter appen til mørk modus, og et hvilket som helst annet tema (også raketten) bytter til lys. Svart og Mørkegrå forblir mørke. Du kan alltid endre det etterpå med 🌙 i menyen eller med Lys Modus i innstillingene.",
    faq_a_water_month: "I vannsporingen. Hver oppføring i dagens logg viser tidspunktet den ble lagt til, og «Månedstabell» åpner hele måneden: hver dag viser hvor mange liter som ble drukket (✓ når dagsmålet ble nådd), og et trykk på en dag viser oppføringene med klokkeslett.",
