    dev_sim_panel_title: "PM – bare for deg",
    faq_a_new_me_weight_optional: "Nei. Både nåværende vekt og målvekt i spørreskjemaet er valgfrie. Hvis en veiing legges til senere (⚖️ Vekt under «Min reise» i New Me eller i vektloggen), regnes fremgangen fra den første.",
