    nm_unlock_desc: "Menyen, utfordringene og reisen er klare – steg for steg, sammen.",
    nm_unlock_title: "New Me er låst opp!",
    room_reveal_star: "En ny stjerne tentes i teleskopet på taket ✨",
    faq_a_room_records: "Platespilleren står i rommet helt fra starten, på trestubben ved lenestolen. Platene åpner de offisielle videoene til store hits fra de siste årene på YouTube, og under dem er det fem rolige melodier som spilles her i rommet – platen snurrer mens de spilles, og «⏹ Stopp» slår av musikken.",
    faq_a_room_roof_gifts: "De kommer med den 8. nøkkelen. Et trykk på teleskopet lar deg se gjennom det: nattehimmelen på nært hold – dra (eller bruk pilene) for å se deg rundt – og de fullførte utfordringene dine danner et stjernebilde i det, én stjerne for hver utfordring; et trykk på en stjerne viser hvilken det var. Et trykk på den lille kisten åpner den – foreløpig er den tom – og et trykk til lukker den.",
    faq_q_room_records: "Hva er det på platespilleren i det hemmelige rommet?",
    faq_q_room_roof_gifts: "Hva er teleskopet og kisten på taket?",
    room_chest_letter: "Et lite brev til deg",
    room_chest_letter_1: "Hvert lille steg på veien var ekte – og hvert eneste ett teller.",
    room_chest_letter_2: "Å være snill mot seg selv er en del av veien, ikke en pause fra den.",
    room_chest_letter_3: "Noen dager er lettere og noen tyngre. Å være der for begge er den ekte styrken.",
    room_chest_letter_4: "Det er lov å hvile. Hvile er også et steg fremover.",
    room_chest_letter_5: "Endringene som varer er de stille – de bygges dag for dag.",
