    faq_a_new_me_preview: "Ja. New Me-siden begynner med en kort video av det som skjer inni: spørreskjemaet, lampene i gangen, ryggsekken, utfordringene og nøklene. Under den står alt som er inkludert, et glimt av én dag og korte svar.",
    faq_q_new_me_preview: "Kan jeg se New Me før jeg kjøper?",
