    ai_chat_food_edit: "✏️ Rett kalorier / protein",
    ai_chat_food_invalid: "Kalorier må være et tall over 0",
    ai_chat_food_updated: "Oppdatert:",
    faq_a_ai_chat_food_fix: "Ja. Under svaret i chatten trykker du på ✏️ Rett kalorier / protein, endrer tallene og trykker på Lagre. Bare det som nettopp ble lagt til endres – også om det ble slått sammen med et mellommåltid som allerede var der. KI kan ta feil, så det lønner seg å sjekke raskt.",
    faq_a_new_me_home_btn: "Med New Me åpner en liten 💎 ved siden av fokusmodus, øverst på startskjermen, dagens meny. Dagens måltider vises også i Min Dag, hvert med en ✓.",
    faq_a_routine_item_days: "Ja. Trykk på punktet i Min Rutine og velg dagene under 📅 Dager – for eksempel bare mandag til fredag. De andre dagene vises det ikke i Min Dag og har ingen ✓; i Min Rutine blir det stående, blekere, med dagene ved siden av. Kortet som spør om et punkt etter 3 dager uten ✓, teller bare punktets egne dager.",
    faq_q_ai_chat_food_fix: "Kan jeg rette kalorier eller protein etter at assistenten har ført opp mat?",
    faq_q_new_me_home_btn: "Hvor er New Me på startskjermen?",
    faq_q_routine_item_days: "Kan ett enkelt punkt i Min Rutine bare gjelde noen dager?",
    routine_item_days_label: "📅 Dager",
    home_note_meal_ph: "Finn et lagret måltid…",
    menu_quick_search: "Hurtigsøk",
    nm_times_hint: "Tips: du kan sette det seneste klokkeslettet du pleier å spise hvert måltid – for eksempel 9:00 hvis du ofte spiser rundt 8.",
    room_game_marquee: "På veien – stopp opp og nyt",
    room_sand_erase_aria: "Gni for å viske ut det som står",
    faq_a_home_note_line: "Skriv på linjen midt på startskjermen og trykk på ➤ (eller Enter) – det lagres i Notater. Trykk på 📝 i starten av linjen, så blir den 🛒: da havner det du skriver på Handlelisten. Trykk én gang til for 🍎: skriv noen bokstaver, de lagrede måltidene som passer dukker opp, og ett trykk fører ett av dem inn i dagens måltider. Med 🎤 kan du bare si det.",
    faq_a_night_mode: "Åpne menyen ☰ og trykk på 🌙 øverst – hele appen blir mørk. ☀️ på samme sted henter dagen tilbake. Det finnes også i Innstillinger, under Lys Modus.",
    faq_q_home_note_line: "Hvordan skriver jeg et hurtignotat fra startskjermen?",
    faq_q_night_mode: "Hvordan bytter jeg til nattmodus?",
    menu_day_mode: "Dagmodus",
    menu_night_mode: "Nattmodus",
    faq_a_secret_room_yoga: "Ved enden av skogsstien står en lysende port, og bak den, ved en foss, sitter skogens skapninger – Lumi, Puffi, Nixie og Sparklet – på mattene sine i en halvsirkel, og Flora, yogalæreren, sitter vendt mot dem på den enslige matten på steinen. Trykk på Flora: hun åpner øynene, alt kommer nærmere, og samtalen begynner rolig, med tid til å lese – Flora spør hvordan alle har det, hver skapning svarer under sitt eget navn (med et lite bilde av den som snakker, ved siden av hver linje), og så spør hun deg hvordan du har det med menneskene som står deg nær. Samtalen fortsetter etter svarene dine – gode mennesker, noen det er vanskelig med, eller å føle seg litt alene. Hver vei ender med et lite oppdrag (det kan legges rett i Min Dag; når oppdraget er å skrive noe, finnes det et sted å skrive det, og det lagres i den magiske dagboken) og en stilling med tre pust sammen. ↩ går ett steg tilbake og ✦ starter en ny samtale. Den neste nøkkelen åpner fossen: når du setter deg på steinen, forsvinner alt, og bare lyden av vannet blir igjen. Når du lener deg over dammen, stiger et spørsmål opp av vannet – hva ville ditt ekte jeg gjort i dag? – og svaret blir en liten oppgave i Min Dag. Det er et vennlig øyeblikk, ikke en erstatning for å snakke med en fagperson.",
    faq_q_secret_room_yoga: "Hva skjer på yogaen i skogen?",
    room_back_to_forest: "Tilbake til stien",
    room_back_to_yoga: "Tilbake til yogaen",
