    room_waterfall_rock_aria: "Sett deg på steinen",
    room_yoga_guide_aria: "Snakk med Flora",
    yg_g_alone: "Takk for at du deler. Det skjer med alle av og til.",
    yg_g_alone_q: "Hva ville føles riktig, om enn bare litt?",
    yg_g_critic: "Kritikk kan stikke lenge. Den handler om ett øyeblikk – ikke om hele mennesket.",
    yg_g_end: "Takk for at du kom til sirkelen. Du kan komme tilbake når du vil.",
    yg_g_gate: "Det er lov å sette en grense. En grense er ingen mur – den er en grind.",
    yg_g_good: "Så fint 💛 Hvem gjorde deg godt denne uka?",
    yg_g_good_msg: "Gode mennesker fortjener å høre det. Et lite takk kan gjøre hele dagen deres.",
    yg_g_hard: "Takk for at du sier det. Hva tynger mest?",
    yg_g_listen: "Å ikke bli hørt er slitsomt. Stemmen din betyr noe, også når den er stille.",
    yg_g_new: "Nye folk begynner med et lite hei. Et kurs, en tur, en gruppe – ett steg.",
