    nm_time_hour: "Time",
    nm_time_minutes: "Minutter",
    routine_time_taken: "Det står allerede noe på dette klokkeslettet: {title}",
    faq_a_new_me_times: "I spørreskjemaet i starten, og når som helst i innstillingene for New Me → «Måltidstider». Hvis rutinen din allerede har måltidstider, hentes de derfra – og rutinens måltider kan skjules, med New Me-måltidene i stedet. Hvis ikke, velger du hvor mange måltider om dagen (2 måltider + et mellommåltid / 2 måltider + en lett middag / 2 måltider + et mellommåltid + en lett middag) og når hvert måltid er. Med «2 måltider + et mellommåltid» blir det lunsj kl. 11:30, mellommåltid kl. 16:00 og middag kl. 19:00 (alle kan endres). Dette er måltidstidene dine overalt: i gangen, i Min Dag, i Min Rutine og i påminnelsene. Uansett hva du velger, blir dagens kalorier de samme – det som tas bort, fordeles på de andre måltidene.",
    faq_q_new_me_times: "Hvordan stiller jeg inn måltidstidene mine i New Me?",
