    faq_a_secret_room_diary: "Bare du. Dagbokssidene lagres i kontoen din, så de finnes på alle enheter, og ingen andre kan se dem. Den magiske dagboken på skrivebordet i det hemmelige rommet åpner den, og det gjør også dagboken i musikkhjørnet. Under den nye siden er det en sammenbrettet månedstabell: en prikk markerer hver dag som har en side, og et trykk på en dag åpner sidene fra den dagen – der kan du også slette en side. Når dagboken er åpnet, kan den også legges i hovedmenyen – med bryteren i selve dagboken eller i New Mes innstillinger.",
    faq_a_secret_room_places: "Hver inngang ved skogsporten åpnes med sin egen nøkkel. Bak dem: verandaen ved havet (på det lille bordet Aladdins lampe – et trykk, og en skogsånd stiger opp av den i en magisk tåke, virvler rundt og starter en samtale om ønsket ditt – se «Hva gjør ånden i lampen?»), gitaren og dagboken (gitaren spiller en kort, rolig melodi og stopper av seg selv, og hver av de tre platene som henger i treet, spiller sin egen magiske melodi – trykk igjen for å stoppe – og i dagboken på stubben skriver du), pusterommet (en stille innsjø i solnedgang – en lotuslykt flyter på vannet: trykk på den, skriv et ønske, så driver den av gårde med det, langt tilbake ut i innsjøen; med tryllestaven kan du skrive i sanden det du vil gi slipp på, og det blir liggende til du visker det bort med fingeren) og skogsstien (den åpnes om natten, og et trykk på lyktene bytter til dag; fra den store grenen henger en magisk huske, på benken kan man sitte, og et trykk på skiltet henter det nær – en tavle med seks små spørsmål å krysse av). På en låst inngang ser du hvor mange nøkler som gjenstår. Ved enden av stien fører en lysende port til yogaen ved fossen – og derfra til selve fossen.",
    faq_q_secret_room_diary: "Hvem ser dagboken?",
    faq_q_secret_room_places: "Hva er bak dørene i gangen?",
