    ai_chat_working_table: "Et øyeblikk, lager tabellen…",
    dev_weather_preview_label: "Forhåndsvisning – bare på kontoen din:",
    faq_a_ai_chat: "Trykk på boblen, så åpnes en chat. Velg hva du vil gjøre – noe til kalenderen, hva du spiste, et bilde av en oppskrift eller en ny tabell – eller bare skriv, så skjønner assistenten det selv. Du kan også trykke på 🎙️ og snakke i stedet for å skrive. For kalenderen kan du velge én gang, hver uke eller hver dag. Svaret kommer i chatten, og derfra kan du gå videre til noe annet eller åpne kalenderen / hva du spiste.",
    faq_a_new_me_hall: "New Me begynner ved porten til en magisk skog, og hver inngang i den er et sted: den runde døren i kjempetreet fører inn i det hemmelige rommet, den hule stokken til verandaen ved havet, sopphuset til gitaren og dagboken, den lille pilebuen til pusterommet, den store pilebuen til skogsstien, og blomsterbuen med stigen fører opp til stjernetaket når det er åpnet. På en låst inngang sitter det en lås. Figuren din, Sky, svever på stien, og rundt omkring er spillknappene: neste oppdrag, ukens utfordring, den magiske ryggsekken med hele New Me, verdenskartet og verktøyene. Et trykk på nøklene øverst forklarer hvordan man får nøkler.",
    faq_a_new_me_routine_meals: "Når måltider er satt opp i New Me og Min Rutine også har måltider, spør New Me om de skal skjules og New Me-måltidene vises i stedet – så ingenting vises to ganger. Min Rutine viser da New Me-måltidene på sine tidspunkter, med 💎 og en ✓ (et trykk på navnet til et måltid åpner et vindu for å velge et annet måltid eller endre tidspunktet, rett der over rutinen). Ingenting slettes: de kommer tilbake via ⚙️ Innstillinger i New Me → Måltider i rutinen, eller ved å slå av «Synkroniser med New Me» under ⚙️ i Min Rutine. Uten en aktiv New Me kommer de tilbake av seg selv.",
    faq_a_room_computer: "Det er en liten chat som begynner med «Hvordan går dagen din så langt?» – bra, travel eller tung – og fortsetter med deg steg for steg, helt frem til et lite oppdrag til slutt (som også kan gå rett inn i Min Dag). Svarene kan trykkes eller skrives fritt – det som skrives, kobles til det nærmeste svaret. «↩ Tilbake» går ett steg tilbake så du kan svare annerledes, og «Ny chat» begynner på nytt når som helst. Etter en travel eller tung dag kan du komme tilbake til datamaskinen senere samme dag: «Jeg er tilbake...» fortsetter samtalen. Det grønne lyset nederst slår datamaskinen av og på. Bare valgene lagres, bare på denne enheten og bare til dagen er slutt.",
    faq_q_ai_chat: "Hvordan snakker jeg med assistenten?",
    faq_q_new_me_hall: "Hva er gangen i New Me?",
