    dictation_btn_aria: "Snakk, så skrives det",
    dictation_mic_denied: "Mikrofonen er blokkert – tillat den via 🔒 ved siden av adressen i nettleseren, eller i telefoninnstillingene",
    faq_a_dictation: "Ja – trykk på mikrofonen 🎤 i hjørnet av hurtignotatet eller en skriveside i notatboka og snakk: ordene skrives mens du snakker, på appens språk. Trykk igjen for å stoppe. Første gang ber nettleseren om lov til å bruke mikrofonen. Fungerer i Chrome / Android og i Safari på iPhone. På en datamaskin trenger du en mikrofon og en nettleser som Chrome, Edge eller Safari – mangler noe, sier meldingen nøyaktig hva.",
    faq_q_dictation: "Kan jeg snakke i stedet for å skrive?",
    faq_a_secret_room: "Et rom som bare er ditt, inne i New Me – et hus inni et kjempetre. Du ser én vegg om gangen og snur deg med pilene (eller ved å sveipe). Den første nøkkelen kommer etter en ✓ på et måltid 3 forskjellige dager og åpner døren – og hele rommet med den: datamaskinen, spillet, platespilleren, hyllen med biblioteket inni og katten. Deretter gir hver fullførte utfordring (også ukens utfordring) en nøkkel som åpner neste sted: stjernetaket, verandaen ved havet, gitaren og dagboken, pusterommet, skogsstien med yoga, fossen og en overraskelse på taket – og den 8. kommer med en flaske fra havet, med brevet fra fortiden inni. Når noe åpnes, viser en pil veien. Den lille luken nederst på spillmaskinen åpnes også – foreløpig er skapet bak den tomt. På stjernetaket faller en stjerne du trykker på som et stjerneskudd, og katten sitter på puten.",
