    room_wall_shelf_hint: "Bøker, notatbøker og minner · døra fører opp til taket",
    room_wall_shelf_title: "Hylla og neste dør",
    room_wall_window_hint: "Trykk på en ting for å komme nærmere · pilene snur rommet",
    room_wall_window_title: "Vinduet og datamaskinen",
    faq_a_steps_in_sport: "Øverst i Treningssporing, i en liten stripe: skrittene i dag og denne uken. Skrittene telles automatisk når appen kobles til Google Fit / Apple Health i telefonversjonen – 🔗-knappen ved siden av forklarer det.",
    faq_q_steps_in_sport: "Hvor er den daglige skrittelleren?",
    sport_steps_today_label: "skritt i dag",
    sport_steps_week_label: "denne uken",
    faq_a_reminders_one_place: "Hver påminnelse kommer én gang, på ett sted. Hvis appen er åpen foran deg (på datamaskinen, iPaden eller telefonen), vises den der; ellers kommer den som varsel bare til telefonen. '✅ Ferdig, takk!' eller 'Skjønner!' hvor som helst lukker den på alle enheter, og den kommer ikke tilbake. 'Ikke ennå' utsetter den: den kommer tilbake hvert 5. minutt, hver gang på ett sted. Å krysse av oppgaven med ✓ i listen teller også som ferdig. For å få varslene også på datamaskin og nettbrett, slå på 'Også på datamaskin og nettbrett' under Innstillinger > Varsler.",
    faq_q_reminders_one_place: "Hvorfor kommer en påminnelse bare én gang, og bare til telefonen?",
    reminder_all_devices_hint: "Som standard kommer hver påminnelse én gang, på ett sted: til telefonen, eller til enheten der appen er åpen foran deg. Ferdig eller Skjønner på ett sted lukker den overalt.",
    reminder_all_devices_label: "Også på datamaskin og nettbrett",
    myday_water_info: "8 middels / små glass vann er i snitt omtrent 2 liter",
    faq_a_good_things: "Om kvelden (fra kl. 18) dukker en liten knapp opp under datoen: skriv opptil 3 gode ting som skjedde i dag – én er nok. De lagres, og under «Tidligere dager» ser du hva du skrev før. «Ikke i kveld» skjuler den til i morgen, og du kan slå den helt av under Innstillinger > Personalisering og kalender.",
    faq_a_home_countdown: "Merk en hendelse med ⭐ i kalenderen (stjernen ved siden av den i hendelseslisten). Den nærmeste merkede hendelsen i løpet av de neste 100 dagene vises under datoen – «3 dager igjen · Mammas bursdag», «I morgen · …» eller «I dag · …». Trykk på den for å gå til den dagen i kalenderen.",
    faq_a_home_streak: "Den teller hvor mange dager på rad du har hatt minst én ✓ – hva som helst i Min Dag, Min Rutine, Mine Mål eller New Me. Den vises fra 2 dager. Har du ingen ✓ i dag ennå, er rekken ikke brutt – hele dagen gjenstår. Og hvis den tar slutt, forsvinner den bare stille, uten dårlig samvittighet.",
    faq_a_home_weather: "Slå på «Vær på himmelen på startskjermen» under Innstillinger > Personalisering og kalender og tillat posisjon. Da viser himmelen på startskjermen det ekte været der du er – sol (eller måne og stjerner om natten), skyer, regn, snø, tordenvær eller tåke – i alle temaer, oppdatert omtrent hvert 40. minutt. Den omtrentlige posisjonen din (avrundet til omtrent 1 km) blir bare på enheten din og sjekkes via serveren vår hos MET Norway. Som standard er det av. Under bryteren står det hvordan været er ute nå – for eksempel ⛅ Delvis skyet, derfor viser himmelen både sol og skyer.",
    faq_q_good_things: "Hva er «3 gode ting fra i dag»?",
    faq_q_home_countdown: "Hvordan får jeg en nedtelling på startskjermen?",
    faq_q_home_streak: "Hva er 🔥 «dager på rad» under hilsenen?",
    faq_q_home_weather: "Hvordan får jeg været på himmelen på startskjermen?",
