    settings_good_things_label: "«3 gode ting» om kvelden",
    settings_weather_hint: "Regn, skyer eller snø i bakgrunnen på startskjermen, etter været der du er. Den omtrentlige posisjonen din blir på denne enheten og sjekkes via serveren vår hos MET Norway.",
    settings_weather_label: "Vær på himmelen på startskjermen",
    weather_failed: "Klarte ikke å sjekke været akkurat nå.",
    weather_location_denied: "Ingen tilgang til posisjonen – tillat den i nettleserinnstillingene og prøv igjen.",
    faq_a_home_focus: "Trykk på ◎ øverst på startskjermen: alt forsvinner unntatt den ene tingen for nå – det som skjer denne timen, eller neste ting på dagens liste – med en stor ✓, pluss Hurtignotat. Etter ✓ dukker neste ting opp. Trykk på 'Fokusmodus ✕' øverst for å få alt tilbake.",
    faq_a_home_search: "Åpne menyen ☰ – søket ligger helt øverst. Skriv minst 2 bokstaver: resultatene kommer fra notatene, handlelisten, kalenderen, oppskrifter, notatbøker (titler og sidetekst), mål, tabeller og bøker, gruppert etter type – trykk på ett for å gå rett dit.",
    faq_a_my_day: "Min Dag samler det som før var En Titt på I Dag og Min Rutine på én tidslinje. Nederst på startskjermen ser du hvor mye som er gjort, hva som skjer nå eller neste (med en rask ✓) og ved siden av tittelen et glass vann med +1. Trykk på den (eller sveip opp) for å åpne hele dagen: øverst det som ikke har klokkeslett, deretter alt time for time – oppgaver, hendelser og møter fra kalenderen, faste ukentlige tider, dagens rutine, de små stegene i målene dine og New Me-måltider – med en linje for nå. Filtrer på Oppgaver, Rutine eller Møter og hendelser. En ✓ her er den samme ✓ som overalt ellers (Min Rutine, Mine Mål, kalenderen) og får en prestekrage i hjørnet til å springe ut. 'Rediger rutinen' åpner Min Rutine (finnes også i menyen), og '＋ Legg til for i dag' legger til en oppgave for i dag. Et trykk på tittelen «Min Dag» (eller på den lille streken øverst) lukker den igjen.",
    faq_q_home_focus: "Hva er fokusmodus?",
    faq_q_home_search: "Hvordan søker jeg i hele appen?",
