    faq_a_table_shopping_link: "I en ✓-kolonne som er koblet til handlelisten (som 'Har ingredienser' i 'Ukens måltider'), har hver rad uten hake en 🛒. Ett trykk legger den til i handlelisten – bare én gang, aldri dobbelt. Sett ✓ her, og den forsvinner fra listen; slett den fra listen, og her vises den ikke lenger som 'på listen'; merk den som kjøpt på listen, og raden her får ✓ av seg selv. Alle ✓-kolonner kan kobles til eller fra i kolonnens innstillinger.",
