    gv_today_title: "Dagens små steg",
    gv_note_text: "Vi trenger ikke være perfekte – bare gjøre litt hver dag for å komme videre.",
    gv_note_title: "På vei mot 10 · vi stopper ikke",
    gv_back: "Tilbake",
    faq_a_food_not_fried_default: "Nei. Med mindre det står (fritert, stekt i olje, schnitzel, panert, pommes frites …), regnes maten som ovnsbakt, grillet eller laget i stekepanne nesten uten olje. 'I stekepanne' betyr høyst litt olje – ikke frityr – og å nevne ovn eller panne endrer ikke porsjonsstørrelsen. Noe fritert? Bare skriv det (for eksempel 'fritert kyllingbryst').",
    faq_q_food_not_fried_default: "Antar AI-en at maten er fritert?",
    faq_a_routine_nudge: "Når noe ikke har blitt krysset av ✓ på mer enn 3 dager (bare dagene det skal gjøres, teller), spør et vennlig kort øverst om det fortsatt er en del av rutinen og om det fungerer – kanskje noe bør endres for å komme videre:\n• ✓ Ja, fortsett – ingen flere spørsmål om det på en uke.\n• ✏️ Endre – åpner det for redigering.\n• 🗑️ Fjern – tar det ut av rutinen.\n• ✕ – ikke nå.\nNår mer enn 3 ting venter (kanskje det var ferie), spør ett enkelt kort om alle samtidig: fortsett som vanlig, eller endre noe – som åpner listen over disse tingene, hver med ✏️ / 🗑️.\nKortet vises bare når ✓-sporing er på og i bruk. Den samme tingen kopiert til flere dagfaner teller som én.",
    faq_q_routine_nudge: "Hvorfor spør Min Rutine om et punkt?",
    faq_a_routine_day_tabs: "Ja. Velg 'Dager for denne fanen' i ⚙️ – de dagene åpnes Min Rutine rett på den, og en liten prikk markerer den. En fane som heter som en dag (f.eks. 'søndag') gjenkjennes automatisk, og dagmalene setter dagene selv. Når en fane har dager, teller ✓-spørsmålet bare dagene der punktene finnes.",
    faq_q_routine_day_tabs: "Kan Min Rutine åpnes på dagens fane?",
    faq_a_routine_add_templates: "Trykk på ➕ i Min Rutine og velg:\n• ✏️ Ny tom fane.\n• 📄 Dupliser gjeldende fane – alle tider og punkter kopieres (uten ✓-historikken). Når en dagsfane som 'søndag' dupliseres, foreslås neste ledige dag automatisk – den raskeste måten å lage en egen rutine for hver dag på.\n• ⭐ Ferdige maler (Premium): én fane for hver dag (søndag–torsdag, mandag–fredag, søndag–fredag eller hele uken) – tomme, eller hver dag som en kopi av gjeldende fane – og 10 ferdige rutiner med innhold: rolig morgen, kveld & god søvn, arbeidsdag, hjemmekontor, studiedag, treningsdag, faste måltider, rolig dag, dag med barna og helg. Alt kan redigeres etterpå.",
    faq_q_routine_add_templates: "Hvordan dupliserer jeg en fane eller bruker en ferdig mal i Min Rutine?",
    routine_tpl_weekend_items: "09:00 Sove lenge + rolig frokost\n11:00 Familie eller venner\n13:00 Lunsj\n15:00 Hvile\n17:00 Tur\n19:00 Middag\n21:00 Film eller rolig kveld",
    routine_tpl_weekend: "Helg",
    routine_tpl_kids_items: "07:00 Stå opp + frokost sammen\n08:00 Levere i barnehage og skole\n14:00 Hente + lunsj\n16:00 Lek eller tid ute\n18:00 Middag\n19:00 Bad + pyjamas\n20:00 Godnatthistorie og sove\n21:00 Tid for meg selv",
    routine_tpl_kids: "Dag med barna",
    routine_tpl_calm_items: "08:00 Kaffe eller te uten mobilen\n10:00 Tur ute\n12:00 Næringsrikt måltid\n15:00 Noe gøy – en hobby\n17:00 Ringe noen kjære\n20:00 Bad eller rolig stund\n22:00 3 gode ting fra i dag",
    routine_tpl_calm: "Rolig dag",
    routine_tpl_eating_items: "08:00 Frokost\n10:00 Vann + frukt\n13:00 Lunsj\n16:00 Mellommåltid\n19:00 Middag\n21:00 Kjøkkenet stengt (vann eller te går fint)",
    routine_tpl_eating: "Faste måltider",
    routine_tpl_workout_items: "07:00 Vann + lett mellommåltid\n08:00 Trening\n09:00 Frokost med protein\n13:00 Balansert lunsj\n16:00 Mellommåltid\n19:00 Middag\n21:00 Tøying\n22:00 Sove 7–8 timer",
    routine_tpl_workout: "Treningsdag",
    routine_tpl_study_items: "08:00 Frokost\n09:00 Studere (50 minutter + 10 pause)\n11:00 Andre studierunde\n13:00 Lunsj + hvile\n14:00 Øve på oppgaver\n16:00 Tur eller trening\n19:00 Repetere dagens stoff\n22:00 Legge seg i tide",
    routine_tpl_study: "Studiedag",
    routine_tpl_home_office_items: "07:00 Stå opp + kle på seg (ikke pyjamas)\n08:00 Frokost + kaffe\n09:00 Fokustid\n11:00 Tøying + vann\n13:00 Lunsj\n14:00 Møter og telefoner\n16:00 Kort tur ute\n17:00 Lukke laptopen",
    routine_tpl_home_office: "Hjemmekontor",
    routine_tpl_workday_items: "07:00 Stå opp + vann\n08:00 Frokost\n09:00 Fokusert arbeid – den viktigste oppgaven\n11:00 Kort pause + vann\n13:00 Lunsj borte fra skjermen\n15:00 E-post og telefoner\n17:00 Avslutte dagen + planlegge i morgen\n19:00 Fritid",
    routine_tpl_workday: "Arbeidsdag",
    routine_tpl_evening_items: "19:00 Lett middag\n20:00 Rydde 10 minutter + gjøre klart til i morgen\n21:00 Skjermene av + dusj\n22:00 Lese i sengen og sove",
    routine_tpl_evening: "Kveld & god søvn",
