    nm_plan_monthly: "Månedlig",
    nm_plan_best: "Best verdi",
    nm_plan_life_sub: "Én betaling – ditt for alltid",
    nm_plan_life: "Livstid",
    faq_a_new_me_tour: "Rett etter kjøpet og det korte spørreskjemaet viser en kort omvisning spillet: topplinjen, neste oppdrag, ukens utfordring, den magiske ryggsekken og dør 1 til det hemmelige rommet. Den kan spilles av igjen når som helst fra ⚙️ Innstillinger > 🧭 Omvisning i New Me – der kan også det fulle navnet fra spørreskjemaet endres. Før kjøp viser New Me en 🔒 i menyen, og et trykk på den åpner en side med alt som er inkludert.",
    faq_q_new_me_tour: "Finnes det en guide til New Me?",
    nm_locked_label: "låst – trykk for å se hva som er inkludert",
    nm_settings_tour: "Omvisning i New Me",
    nm_tour_done_text: "Omvisningen kan vises igjen når som helst via ⚙️ Innstillinger.",
    nm_tour_done_title: "Klar til å starte 💪",
    nm_tour_tiles_text: "Reisen og prestasjonene, handlelisten, målene, bildene, månedskalenderen, påminnelsene og menyens PDF.",
    nm_tour_tiles_title: "Alt annet",
    nm_tour_challenges_text: "20 utfordringer å velge mellom, som starter når du bestemmer – og på slutten venter en gave.",
