    nm_gift_locked_view: "Gaven åpnes etter alle {n} utfordringene – {left} igjen.",
    nm_gift_intro: "Alle {n} utfordringene, steg for steg. Dette ventet:",
    nm_gift_title: "Gaven din",
    faq_a_new_me_letter_gift: "I starten av New Me (eller senere, under Utfordringer) kan du skrive et brev til deg selv i fremtiden. Når det er forseglet, kan det ikke leses eller endres før det åpnes: i flasken fra havet i det hemmelige rommet, eller når alle de 20 utfordringene er fullført – der venter også en gave.",
    faq_q_new_me_letter_gift: "Hva er brevet fra fortiden?",
    faq_a_new_me_challenges: "🏆 Utfordringer har 20 utfordringer: 10 store (som 5 dager uten sukker, en uke uten karbohydrater eller gå ned 4 kg på en måned – kaloriunderskudd, trening og ikke sukker hver dag) og 10 mini – små vaner i en uke, som kanelkaffe uten sukker. Når en utfordring velges, kommer spørsmålet om når den skal starte: i dag, i morgen, neste uke eller en annen dato. En stor og en miniutfordring kan pågå samtidig. En pågående utfordring vises øverst i menyen og i Min Dag, med en ✓ for dagen. Hver uke av en utfordring gir én fri dag (🍕) som ikke bryter den, og en dag som ikke er krysset av, teller som fri dag – i dag og i går kan krysses av. Noen dager krysses av automatisk: en økt på 20 minutter i Treningssporing, eller menyens måltider med ✓. Hver utfordring har en ⓘ med hva som teller (for eksempel hele listen over karbohydrater) – i selve utfordringen og ved siden av i Min Dag. Under dem har 🌱 Personlig utvikling 48 små utfordringer for én uke (de teller ikke med i de 20) – se «Hva er ukens utfordring?».",
    faq_q_new_me_challenges: "Hvordan fungerer utfordringene i New Me?",
    nm_letter_too_short: "Noen ord til 🙂",
    nm_letter_quiz_note: "Valgfritt – det kan også skrives senere, under Utfordringer.",
