    nm_letter_sealed_toast: "Forseglet ✉️ – vi ses ved målstreken",
    nm_letter_seal_note: "Når brevet er forseglet, kan det ikke leses eller endres før alle utfordringene er fullført.",
    nm_letter_seal: "✉️ Forsegl brevet",
    nm_letter_ph: "Hvor jeg er i dag, hvor jeg vil komme, hva som er vanskelig for meg med mat, hva jeg vil si til meg selv ved målstreken…",
    nm_letter_intro: "Skrives nå og forsegles – åpnes først etter alle {n} utfordringene, for å se hvor mye som har endret seg siden. Hvor er jeg nå? Hva er målene mine, og hva er vanskelig for meg med mat?",
