    nm_tile_challenges: "Utfordringer",
    faq_a_workout_calories: "Ja. Hver treningsøkt får et anslag over forbrente kalorier – ut fra type, varighet og din siste vekt (ved løping og sykling også ut fra fart, når en distanse er lagt inn). Det vises i treningslisten og i månedsoversikten (Forbrent) og legges til dagens kaloribudsjett: i Daglig Måltidssporer, i Kalori- og vektstatistikk og i New Me-ringen. Det er et anslag, derfor vises det med ~.",
    faq_q_workout_calories: "Teller trening med i dagens kalorier?",
    faq_a_new_me_flexible_menu: "Ja. I spørreskjemaet og i innstillingene velger du hvor mange måltider om dagen – 2 måltider + et mellommåltid / 2 måltider + en lett middag / 2 måltider + et mellommåltid + en lett middag – og ➖ på et måltidskort fjerner det (minst 3 blir igjen); «➕ Legg tilbake» henter det tilbake. Uansett blir dagens kalorier de samme: det som tas bort, fordeles på de andre måltidene, og under hvert måltid står det hvor mye som ble lagt til og hva som passer til. ✏️ Rediger på et måltid åpner teksten – endre det du vil (f.eks. uten brød eller med ett egg til), så regner AI ut kalorier og protein på nytt. 🔄 Bytt gir valg fra menyen, ⭐ Lagrede og ✨ Skriv selv; hver endring kan gjelde bare i dag eller fra nå av. Og nederst i «Hele dagen» finnes ➕ Legg til mat – skriv hva som ble spist utenfor menyen, så regner AI det ut og legger det til i dag (✕ sletter).",
