    faq_a_goal_days_challenge: "Trykk på ＋ i Mine Mål (eller på det ferdige eksemplet '🔥 8 dager'), velg '📆 Dagersutfordring', skriv inn antall dager og legg til hva du gjør hver dag (f.eks. 'En gåtur på 30 minutter', 'Spise etter menyen min'). Kryss av dagens oppgaver hver dag under utfordringens sti – når alle er krysset av, teller dagen, stien flytter seg én stein frem og 🔥-rekken din vokser (uten daglige oppgaver finnes det én knapp, '✓ Jeg klarte det i dag'). 🔁-knappen ved siden av en oppgave legger den til i Min Rutine på en time du velger: krysser du den av der, krysses den også av i målet, og omvendt. Milepæler i et vanlig mål kan legges til i Min Rutine på samme måte.",
