    vision_focus_ribbon: "🎯 Månedens mål",
    vision_tagline: "Store mål, små steg.",
    faq_a_app_tour: "Omvisningen åpnes automatisk én gang, første gang du kommer inn. Den begynner med delene sine – trykk på en for å gå rett dit – og viser så alle deler av appen (startskjermen, AI-assistenten og hvert menypunkt) og de fem gruppene i Innstillinger, hver med en kort forklaring, og kikker inn i noen av dem (for eksempel en eksempelsti for et mål, vesken og Google Calendar). Fortsett går videre, Tilbake går tilbake, Hopp over denne delen hopper til neste del og ✕ lukker omvisningen. Du kan se den igjen når som helst under Innstillinger > Hjelp og bruk > Appomvisning, og fortsette der du slapp. Fortsett og Tilbake er alltid på samme sted nederst på skjermen, og på en datamaskin fungerer piltastene også.",
    faq_q_app_tour: "Hvordan ser jeg appomvisningen igjen?",
    apptour_done_text: "Har du et spørsmål? Hjelp og ofte stilte spørsmål i Innstillinger svarer på alt, og denne omvisningen finner du alltid under Hjelp og bruk.",
