    apptour_s_notifications_text: "Påminnelsesvarsler og lyden deres. '⏰ Ikke ennå' på en påminnelse fungerer som slumreknappen på en vekkerklokke: du blir påminnet igjen hvert 5. minutt.",
    apptour_s_personalization_text: "Land, måltider og mellommåltider per dag, når den økonomiske måneden din starter og hva som vises på startskjermen.",
