    apptour_routine_text: "Din daglige rutine time for time, i faner (barn, studier, jobb…). Kryss av ✓ hver dag for å bygge vaner og rekker; 📅 viser hele måneden.",
    apptour_premium_text: "Låser opp hele AI-assistenten, temaer, skrifttyper, Min veske og mer.",
