    nm_drinks_hint: "Bare skriv inn drikken – kaloriene beregnes automatisk, og tallet kan endres.",
    nm_slot_drinks: "Drikke",
    faq_a_new_me_tracking: "Trykk på neste oppdrag øverst i New Me og deretter på ✓ Spist for å markere neste måltid som spist – hele menyen med ✓ på hvert måltid finnes under Hele dagen, på siden, og dagens måltider vises også i Min Dag på startskjermen – et trykk på ett av dem der (eller musen over det) viser nøyaktig hva som skal spises, med ✓ og Bytt. Alt synkroniseres med Daglig Måltidssporer: planens måltider, drikke og alt du legger til andre steder (f.eks. en kaffe fra hurtigtillegg) telles sammen i New Me og i Min Dag – ingenting du allerede har skrevet, blir overskrevet, og å fjerne en ✓ fjerner bare New Me-delen. Når alle dagens måltider er huket av, blir det en liten feiring. Under «Drikke» føres dagens drikke – til sammen opptil ~150 kcal, altså omtrent 3 drikker på opptil ~50 kcal hver. Bare skriv navnet på drikken, så fylles kaloriene inn automatisk med AI. De to radene for kaffe/te har også feltet «Melk? Hvor mye?» (f.eks. «litt» eller «50 ml»), og beregningen oppdateres; tallet kan endres både før og etter at drikken er lagt til. En drikke med navn og kalorier lagres automatisk så snart du går videre – å trykke på Legg til er valgfritt. Trykk på ☆ ved siden av en drikke for å lagre den som fast drikke – faste drikker vises som knapper øverst i Drikke-kortet, og ett trykk legger dem til for dagen. ⭐ lagrer et måltid som lagret måltid. «Dagstabell» viser hva du har spist, med kalorier og protein. Den lille 💎 ved siden av fokusmodus, øverst på startskjermen, åpner det direkte. Kalori- og proteinverdier er AI-anslag og kan inneholde feil. Spiste du ikke alt? Under et avhuket måltid trekker «Spiste ikke alt?» fra en fjerdedel, halvparten eller tre fjerdedeler av porsjonen – eller det du skriver, utregnet – og dagens kalorier oppdateres.",
    faq_q_new_me_tracking: "Hvordan fungerer ✓, bytter og kalorier i New Me?",
    faq_a_new_me_what: "New Me er et eget dagsmenyprogram med to ferdige planer – 1 300 eller 1 500 kalorier – bygget på 2 hovedmåltider og 2 mellommåltider, med 3 alternativer for hvert. Hele Premium er inkludert. Pris: $11.99 i måneden (si opp når som helst) eller $99.99 én gang, livstid. Det åpnes via 💎 New Me i menyen. Før start er det et kort spørreskjema som begynner med en medisinsk ansvarsfraskrivelse som må godtas. Programmet er bare generell informasjon og erstatter ikke lege eller klinisk ernæringsfysiolog.",
    faq_q_new_me_what: "Hva er New Me, og hvordan får jeg det?",
