    settings_accessibility_statement_link: "♿ Tilgjengelighetserklæring",
    recurring_task_tooltip: "Ukentlig gjentakende oppgave",
    quick_add_ai_limit_toast: "Månedens AI-kvote er brukt opp, så et raskere (mindre presist) estimat ble brukt i stedet. Den nullstilles neste måned.",
    food_estimate_local_db_reasoning: "Funnet i matdatabasen vår, ikke gjettet av AI. Trykk på «Stemmer ikke» hvis dette ikke er matvaren du mente.",
    food_clarify_milk_question: "Er {ingredient} en melkeerstatning blandet i drikken, eller en egen porsjon fast føde? Oppgi også mengden.",
    food_ai_fallback_toast: "Fikk ikke tak i det fullstendige AI-estimatet akkurat nå, så dette er et raskt, grovt estimat i stedet. Du kan redigere kaloriene manuelt eller prøve å loggføre på nytt om litt.",
    daily_focus_badge_title: "Påminnelse: det viktigste i dag",
    calendar_event_star_title: "Merk som viktig",
    auth_password_placeholder_login: "Passord",
    routine_overview_no_checks: "Ingen avkrysninger denne måneden ennå - trykk på ✓ ved siden av rutinepunktene dine de dagene du gjør dem.",
    faq_a_finance_cycle_day: "Som standard nullstilles budsjettoversikten din den 1. i hver kalendermåned. Får du lønn en annen dag (for eksempel den 10.), setter du den dagen her i stedet - månedsoversikten, historikken og målbudsjettet ditt går da fra den dagen til samme dag neste måned, i stedet for fra den 1. til slutten av måneden.",
    faq_q_finance_cycle_day: "Hva gjør innstillingen 'Nullstillingsdag for månedsbudsjett'?",
    faq_a_quick_note_view_full_lists: "I menyen ☰ finner du Notater og Handleliste med en gang. I vinduet Hurtignotat (i Fokusmodus) tar de små 📝 og 🛒 ved siden av Legg til deg også dit, og 🍎 legger raskt inn et av de lagrede måltidene dine.",
    faq_q_quick_note_view_full_lists: "Hvordan ser jeg alle Notatene mine eller hele Handlelisten fra Hurtignotat?",
