    daily_focus_c7_d0: "Huske hva jeg har, ikke bare det som mangler", daily_focus_c7_d1: "Slippe taket på det som er utenfor min kontroll", daily_focus_c7_d2: "Verdsette lærdommen selv når ting ikke går som planlagt", daily_focus_c7_d3: "Stoppe opp et øyeblikk og si takk for det jeg har", daily_focus_c7_d4: "Stole på meg selv og min evne til å takle ting", daily_focus_c7_d5: "Bringe meg selv tilbake til en sunn følelse av proporsjon",
    daily_focus_p1_d1_s1: "Beskytte min rolige plass midt i presset rundt meg", daily_focus_p1_d1_s2: "Lytte til hva kroppen og sjelen min trenger i dag", daily_focus_p1_d1_s3: "Holde ordene mine oppmuntrende, tålmodige og forståelsesfulle", daily_focus_p1_d1_s4: "Ta små steg som skaper ren fremgang", daily_focus_p1_d1_s5: "Bringe et smil og letthet inn i alt jeg gjør",
