    faq_q_daily_focus_prompt: "Hva er den lille påminnelsen som spør hva som er viktigst for meg å gjøre i dag?", faq_a_daily_focus_prompt: "Det er en daglig Premium-påminnelse: én gang om dagen dukker det opp et lite «1»-merke på AI-assistentens ikon. Trykk på merket for å åpne en boble som spør hva som er viktigst for deg å gjøre i dag, med 5 ferdige forslag rett i den (de byttes ut daglig og roterer gjennom et helt år med ulike temaer, så de holder seg friske) pluss 'Annet' for å skrive ditt eget - du kan velge mer enn ett. Trykk på Legg til, så vises valgene dine som små påminnelsesmerker øverst i 'Min Dag' (de er ikke oppgaver som skal krysses av). Lukker du den med ✕ eller trykker utenfor, blekner merket bare resten av dagen i stedet for å forsvinne. Den er på som standard, men du kan slå den av under Innstillinger > Personalisering og kalender. Ikke riktig dag? Trykk på '🌙 Ikke i dag' – merket forsvinner til i morgen, og så kommer spørsmålet tilbake som vanlig. Ett av forslagene kommer fra ditt eget liv – neste steg i månedens mål eller dagens lesing. Hver dag starter på nytt.",
